/*
 * A170419  Number of reduced words of length n in Coxeter group on 26
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^44 = I.
 * https://oeis.org/A170419
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) satisfies the recurrence a(0) = 1, a(1) = 26, a(n) =
 *            24·(a(n-1)+…+a(n-43)) – 300·a(n-44) + p(n) for n ≥ 1, where p(0)
 *            = 1, p(n) = 2 for 1 ≤ n ≤ 43, p(44) = 1, p(n) = 0 for n ≥ 45.
 *            The sequence is generated by the rational function (1 + 2t + 2t²
 *            + … + 2t⁴³ + t⁴⁴) / (1 – 24t – 24t² – … – 24t⁴³...
 * Range:     u8 n <= 1, u16 n <= 3, u32 n <= 6, u64 n <= 13, u128 n <= 15,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* Static cache of already computed terms. */
    static seq_t *cache   = NULL;     /* sequence values a(0) … a(max_computed)   */
    static idx_t  cache_len = 0;      /* number of allocated slots              */

    /* Grow the cache if necessary. */
    if (n + 1 > cache_len) {
        idx_t old_len = cache_len;
        cache_len = n + 1;
        cache = (seq_t *)realloc(cache, cache_len * sizeof(seq_t));
        if (old_len == 0) {          /* first allocation: set a(0) */
            cache[0] = (seq_t)1;
            old_len = 1;
        }
        /* Compute missing terms in order. */
        for (idx_t i = old_len; i <= n; ++i) {
            /* Sum the last 43 terms (or fewer if i < 43). */
            seq_t sum_prev = 0;
            for (idx_t k = 1; k <= 43 && k <= i; ++k) {
                sum_prev += cache[i - k];
            }

            /* Term involving a(i-44). 0 if i < 44. */
            seq_t term44 = 0;
            if (i >= 44) {
                term44 = (seq_t)300 * cache[i - 44];
            }

            /* Resulting p(i) value. */
            seq_t p = 0;
            if (i == 0)          p = 1;
            else if (i == 44)    p = 1;
            else if (i <= 43)    p = 2;
            /* else p stays 0. */

            cache[i] = (seq_t)24 * sum_prev - term44 + p;
        }
    }

    return cache[n];
}
